package org.telegram.ui.Components;

import android.view.Gravity;
import android.view.View;
import android.widget.*;
import org.telegram.messenger.*;
import org.telegram.messenger.devgram.nodes.NodePackageFiles;
import org.telegram.ui.ActionBar.*;
import org.telegram.ui.DevGramAppearanceAccess;
import java.util.*;

/** Source store layout: title/update-all, a 360dp list, version, description and action per package. */
public final class DevGramNodeStoreUi {
 private final BaseFragment host;private final int account;private final long uid;private final LinearLayout list;private final TextView update;private final BottomSheet sheet;private List<NodePackageFiles.Entry> packages=new ArrayList<>();private boolean closed,busy;private int generation;
 private final Runnable policy=()->{if(!allowed())sheetDismiss();};
 private String t(String s){return DevGramLocale.text(s);}private boolean allowed(){return !closed&&host.getCurrentAccount()==account&&host.getUserConfig().getClientUserId()==uid&&DevGramProfileCustomization.enabled()&&DevGramProfilePolicy.allowed(uid,"avatar.nodes");}
 public static void show(BaseFragment host){if(host.getParentActivity()!=null&&DevGramProfileCustomization.enabled()&&DevGramAppearanceAccess.check(host,"avatar.nodes"))new DevGramNodeStoreUi(host);}
 private DevGramNodeStoreUi(BaseFragment host){this.host=host;account=host.getCurrentAccount();uid=host.getUserConfig().getClientUserId();LinearLayout body=DevGramStudioControls.column(host.getParentActivity());body.setPadding(AndroidUtilities.dp(20),AndroidUtilities.dp(18),AndroidUtilities.dp(20),AndroidUtilities.dp(18));LinearLayout heading=new LinearLayout(body.getContext());heading.setGravity(Gravity.CENTER_VERTICAL);TextView title=DevGramStudioControls.text(body.getContext(),"Ноды с сервера",18,true,host.getResourceProvider());heading.addView(title,new LinearLayout.LayoutParams(0,-2,1));update=button("Обновить все");update.setOnClickListener(v->updateAll(0));heading.addView(update);body.addView(heading);ScrollView scroll=new ScrollView(body.getContext());list=DevGramStudioControls.column(body.getContext());list.setPadding(0,AndroidUtilities.dp(12),0,0);scroll.addView(list);body.addView(scroll,new LinearLayout.LayoutParams(-1,AndroidUtilities.dp(360)));sheet=new BottomSheet.Builder(body.getContext(),true,host.getResourceProvider()).setCustomView(body).create();DevGramProfilePolicy.listen(policy);host.showDialog(sheet,d->{closed=true;generation++;DevGramProfilePolicy.unlisten(policy);});load();}
 private void sheetDismiss(){sheet.dismiss();}
 private TextView button(String label){TextView view=DevGramStudioControls.text(host.getParentActivity(),label,14,true,host.getResourceProvider());view.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText,host.getResourceProvider()));view.setGravity(Gravity.CENTER);view.setPadding(AndroidUtilities.dp(12),AndroidUtilities.dp(8),AndroidUtilities.dp(12),AndroidUtilities.dp(8));view.setBackground(Theme.createSimpleSelectorRoundRectDrawable(AndroidUtilities.dp(10),0x223390ec,0x443390ec));return view;}
 private void load(){if(!allowed()||busy)return;int request=++generation;list.removeAllViews();list.addView(DevGramStudioControls.text(list.getContext(),"Загрузка…",14,false,host.getResourceProvider()));DevGramNodePackages.catalog((entries,error)->{if(!allowed()||request!=generation)return;if(entries==null||entries.isEmpty()){list.removeAllViews();TextView retry=button(error==null?"На сервере нод нет":"Не удалось получить список · Повторить");retry.setOnClickListener(v->load());list.addView(retry);return;}packages=entries;render(error);});}
 private void render(String error){list.removeAllViews();if(error!=null)list.addView(DevGramStudioControls.text(list.getContext(),"Сервер недоступен. Показаны установленные пакеты.",12,false,host.getResourceProvider()));for(NodePackageFiles.Entry entry:packages){LinearLayout row=new LinearLayout(list.getContext());row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,AndroidUtilities.dp(10),0,AndroidUtilities.dp(10));LinearLayout labels=DevGramStudioControls.column(list.getContext());TextView name=DevGramStudioControls.text(list.getContext(),"",15,true,host.getResourceProvider());name.setText(t(entry.name)+"  v"+entry.version);labels.addView(name);labels.addView(DevGramStudioControls.text(list.getContext(),entry.hint,12,false,host.getResourceProvider()));row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));int current=DevGramNodePackages.version(entry.pkg);TextView action=button(current==0?"Установить":current<entry.version?"Обновить":"Установлено");action.setEnabled(!busy);action.setOnClickListener(v->{if(current==0||current<entry.version)install(entry);else host.showDialog(new AlertDialog.Builder(host.getParentActivity(),host.getResourceProvider()).setTitle(t(entry.name)).setMessage(t("Версия пакета")+": "+current).setPositiveButton(t("Удалить"),(d,w)->{if(!allowed()||busy)return;busy=true;DevGramNodePackages.remove(entry,(success,failure)->{busy=false;if(!allowed())return;if(!success)error();load();});}).setNegativeButton(t("Закрыть"),null).create());});row.addView(action);list.addView(row);}update.setEnabled(!busy);}
 private void install(NodePackageFiles.Entry entry){if(!allowed()||busy)return;busy=true;render(null);DevGramNodePackages.install(entry,(success,error)->{busy=false;if(!allowed())return;if(!success)error();load();});}
 private void updateAll(int at){if(!allowed())return;if(at==0){if(busy)return;busy=true;update.setText(t("Обновляю…"));render(null);}while(at<packages.size()&&DevGramNodePackages.version(packages.get(at).pkg)>=packages.get(at).version)at++;if(at>=packages.size()){busy=false;update.setText(t("Обновить все"));load();return;}int next=at+1;DevGramNodePackages.install(packages.get(at),(success,failure)->{if(!allowed())return;if(!success){busy=false;update.setText(t("Обновить все"));error();load();return;}updateAll(next);});}
 private void error(){BulletinFactory.of(host).createErrorBulletin(t("Пакет не прошёл проверку или не удалось сохранить файлы.")).show();}
}
